(() => {
'use strict';const $=s=>document.querySelector(s),core=window.CompoundLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
const symbol={'<':'<','<=':'\\le','>':'>','>=':'\\ge'};const pct=x=>(x+6)*100/12;
function line(label,intervals,x){const row=document.createElement('div');row.className='compound-line';const title=document.createElement('div');title.className='compound-row-label';title.textContent=label;const track=document.createElement('div');track.className='compound-track';track.setAttribute('role','img');track.setAttribute('aria-label',label+': '+(intervals.length?intervals.map(i=>`${i.lc?'termasuk':'tanpa'} batas ${Number.isFinite(i.lo)?i.lo:'negatif tak hingga'} sampai ${Number.isFinite(i.hi)?i.hi:'positif tak hingga'} ${i.hc?'termasuk':'tanpa'} batas kanan`).join('; '):'himpunan kosong'));for(let tick=-4;tick<=4;tick+=2){const e=document.createElement('span');e.className='compound-tick';e.dataset.tex=String(tick);e.style.left=pct(tick)+'%';e.setAttribute('aria-hidden','true');track.append(e);}for(const i of intervals){if(i.lo<i.hi){const band=document.createElement('span');band.className='compound-band';band.style.left=pct(Math.max(-6,i.lo))+'%';band.style.width=(Math.min(6,i.hi)-Math.max(-6,i.lo))*100/12+'%';track.append(band);}for(const [v,closed] of [[i.lo,i.lc],[i.hi,i.hc]]){if(Number.isFinite(v)){const end=document.createElement('span');end.className='compound-end'+(closed?' closed':'');end.style.left=pct(v)+'%';track.append(end);}else{const arrow=document.createElement('span');arrow.className='compound-arrow '+(v<0?'left':'right');track.append(arrow);}}}if(!intervals.length){const e=document.createElement('span');e.className='compound-empty';e.textContent='Tidak ada nilai yang memenuhi';track.append(e);}const trial=document.createElement('span');trial.className='compound-trial';trial.style.left=pct(x)+'%';track.append(trial);row.append(title,track);return row;}
function draw(){const ra=$('#relation-a').value,rb=$('#relation-b').value,a=Number($('#bound-a').value),b=Number($('#bound-b').value),op=$('#compound-operation').value,x=Number($('#trial-value').value),A=core.ray(ra,a),B=core.ray(rb,b),result=core.combine(A,B,op),hitA=core.contains(A,x),hitB=core.contains(B,x),hit=result.some(i=>core.contains(i,x));$('#output-a').value=a;$('#output-b').value=b;$('#trial-output').value=String(x).replace('.',',');math($('#compound-equation'),`x${symbol[ra]}${a}\\quad\\text{${op==='and'?'dan':'atau'}}\\quad x${symbol[rb]}${b}`);math($('#compound-result'),`S=${core.intervalTex(result)}`);$('#compound-lines').replaceChildren(line('Syarat A',[A],x),line('Syarat B',[B],x),line(op==='and'?'Hasil: irisan':'Hasil: gabungan',result,x));$('#compound-feedback').textContent=`Nilai uji ${String(x).replace('.',',')}: syarat A ${hitA?'dipenuhi':'tidak dipenuhi'}, syarat B ${hitB?'dipenuhi':'tidak dipenuhi'}. ${hit?'Diterima':'Tidak diterima'} oleh hasil ${op==='and'?'irisan: kedua syarat harus dipenuhi.':'gabungan: minimal satu syarat harus dipenuhi.'}`;}
for(const id of ['relation-a','relation-b','compound-operation'])$('#'+id).addEventListener('change',draw);for(const id of ['bound-a','bound-b','trial-value'])$('#'+id).addEventListener('input',draw);
function preset(ra,a,rb,b,op){$('#relation-a').value=ra;$('#bound-a').value=a;$('#relation-b').value=rb;$('#bound-b').value=b;$('#compound-operation').value=op;$('#trial-value').value=2;draw();}
$('#example-overlap').addEventListener('click',()=>preset('>=',0,'<=',2,'or'));$('#example-empty').addEventListener('click',()=>preset('>',3,'<',-1,'and'));$('#example-point').addEventListener('click',()=>preset('>=',2,'<=',2,'and'));$('#example-hole').addEventListener('click',()=>preset('<',2,'>',2,'or'));$('#reset-compound').addEventListener('click',()=>{$('#trial-value').value=0;preset('>',-1,'<=',3,'and');$('#trial-value').value=0;draw();});draw();
const questions=[
[String.raw`x>-1\ \text{dan}\ x\le3`,[String.raw`(-1,3]`,String.raw`[-1,3]`,String.raw`(-\infty,3]`],0,'Harus memenuhi kedua syarat. Negatif satu tidak ikut, tiga ikut.'],
[String.raw`x<-1\ \text{atau}\ x\ge3`,[String.raw`(-1,3)`,String.raw`(-\infty,-1)\cup[3,\infty)`,String.raw`[-1,3]`],1,'Atau menerima salah satu daerah di luar, bukan daerah di tengah.'],
[String.raw`x>3\ \text{dan}\ x<-1`,[String.raw`\mathbb R`,String.raw`\{0\}`,String.raw`\varnothing`],2,'Tidak ada bilangan yang sekaligus lebih besar dari tiga dan lebih kecil dari negatif satu.'],
[String.raw`x\ge2\ \text{dan}\ x\le2`,[String.raw`\varnothing`,String.raw`\{2\}`,String.raw`(2,2)`],1,'Hanya nilai dua yang memenuhi keduanya. Himpunan satu titik berbeda dari interval terbuka dengan kedua batas sama.'],
[String.raw`x\ge0\ \text{atau}\ x\le2`,[String.raw`[0,2]`,String.raw`\mathbb R`,String.raw`\varnothing`],1,'Nilai di daerah tumpang tindih tetap diterima. Semua bilangan real memenuhi setidaknya satu syarat.'],
[String.raw`-4\le-2x<6`,[String.raw`[-2,3)`,String.raw`(-3,2]`,String.raw`[-3,2)`],1,'Bagi ketiga bagian dengan negatif dua dan balik kedua tanda. Hasilnya dua lebih besar atau sama dengan masukan, dan masukan lebih besar dari negatif tiga.'],
[String.raw`[1,3]\cap(3,5)`,[String.raw`\{3\}`,String.raw`[1,5)`,String.raw`\varnothing`],2,'Tiga termasuk interval pertama tetapi tidak interval kedua, jadi tidak ada bagian yang sama.'],
[String.raw`[1,3]\cup(3,5)`,[String.raw`[1,5)`,String.raw`[1,3)\cup(3,5)`,String.raw`(1,5]`],0,'Titik tiga sudah termasuk interval pertama. Gabungannya menyambung tanpa lubang, dengan satu termasuk dan lima tidak.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`compound-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#compound-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#compound-questions').append(box);});$('#compound-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#compound-reflection').value=localStorage.getItem('fondasi-compound-reflection')||'';}catch{$('#compound-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#compound-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-compound-reflection',$('#compound-reflection').value);$('#compound-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#compound-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
